define(["jquery", "comm", "./cell_renderer", "./map_knowledge", "./options",
    "./tileinfo-dngn", "./util", "./view_data", "./enums", "./mouse_control", "./game-context", "tooltip-policy", "./party-hover", "./traversal-effects", "./shell-animation", "./planned-route", "./chunked-view", "./sprite-reach", "./premium-movement", "./premium-effects", "./premium-regions", "./chain-view"],
function ($, comm, cr, map_knowledge, options, dngn, util, view_data, enums,
    mouse_control, game, tip_policy, presence, traversal, shells, plannedRoute, chunks, spriteReach, movement, effects, regions, chains) {
    "use strict";
    var global_anim_counter = 0;
    var last_background_tick = -1;

    function is_torch(basetile)
    {
        return (basetile == dngn.WALL_BRICK_DARK_2_TORCH
                || basetile == dngn.WALL_BRICK_DARK_4_TORCH
                || basetile == dngn.WALL_BRICK_DARK_6_TORCH);
    }

    function background_is_animated(cell)
    {
        if (cell == null || cell.bg == null) return false;
        var base_bg = dngn.basetile(cell.bg.value);
        if (base_bg >= dngn.DNGN_LAVA && base_bg < dngn.FLOOR_MAX)
            return options.get("tile_water_anim");
        else if ((base_bg >= dngn.DNGN_ENTER_ZOT_CLOSED && base_bg < dngn.DNGN_CACHE_OF_FRUIT)
                 || (base_bg >= dngn.DNGN_SILVER_STATUE && base_bg < dngn.ARCANE_CONDUIT)
                 || (base_bg >= dngn.ARCANE_CONDUIT && base_bg < dngn.STORM_CONDUIT)
                 || (base_bg >= dngn.WALL_STONE_CRACKLE_1 && base_bg <= dngn.WALL_STONE_CRACKLE_4)
                 || is_torch(base_bg) || base_bg == dngn.DNGN_TRAP_HARLEQUIN)
        {
            return options.get("tile_misc_anim");
        }
        else
            return false;
    }

    function animate_cell(cell)
    {
        if (!background_is_animated(cell)) return;
        var base_bg = dngn.basetile(cell.bg.value);
        if (base_bg == dngn.DNGN_PORTAL_WIZARD_LAB
            || base_bg == dngn.DNGN_EXIT_NECROPOLIS
            || base_bg == dngn.DNGN_ALTAR_JIYVA
            || base_bg == dngn.DNGN_TRAP_HARLEQUIN
            || base_bg >= dngn.ARCANE_CONDUIT && base_bg < dngn.STORM_CONDUIT
            || is_torch(base_bg))
        {
            cell.bg.value = base_bg + (cell.bg.value - base_bg + 1) % dngn.tile_count(base_bg);
        }
        else if ((base_bg > dngn.DNGN_LAVA && base_bg < dngn.BLOOD) ||
                 (base_bg >= dngn.WALL_STONE_CRACKLE_1 && base_bg <= dngn.WALL_STONE_CRACKLE_4) ||
                 (base_bg >= dngn.DNGN_SILVER_STATUE && base_bg < dngn.ARCANE_CONDUIT))
        {
            cell.bg.value = base_bg + Math.floor(Math.random() * dngn.tile_count(base_bg))
        }
        else if (base_bg == dngn.DNGN_LAVA)
        {
            var tile = (cell.bg.value - base_bg) % 4;
            cell.bg.value = base_bg + (tile + 4 * global_anim_counter) % dngn.tile_count(base_bg);
        }
    }

    function DungeonViewRenderer()
    {
        cr.DungeonCellRenderer.call(this);

        this.cols = 0;
        this.rows = 0;

        this.view = { x: 0, y: 0 };
        this.view_center = { x: 0, y: 0 };
        this.ui_state = -1;
        this.last_sent_cursor = { x: 0, y: 0 };
    }

    DungeonViewRenderer.prototype = new cr.DungeonCellRenderer();

    $.extend(DungeonViewRenderer.prototype, {
        init: function (element)
        {
            var renderer = this;
            // Older server templates put the canvas directly in the column.
            // Give every presentation layer the same bounded coordinate frame.
            if (element.id === "dungeon" && element.parentElement.id !== "dungeon_viewport") {
                var viewport = document.createElement("div"); viewport.id = "dungeon_viewport";
                element.parentElement.insertBefore(viewport, element); viewport.appendChild(element);
            }
            $(element)
                .attr({ tabindex: "0", "aria-haspopup": "menu", "aria-label": "Dungeon. Right-click a tile for actions." })
                .off("update_cells mousemove mouseleave mousedown contextmenu keydown.dungeonContext")
                .on("update_cells", function (ev, cells) {
                    $.each(cells, function (i, loc) {
                        map_knowledge.touch(loc.x, loc.y);
                    });
                    $(document).trigger("dungeon_tiles_changed", [cells]);
                })
                .on("mousemove mouseleave mousedown contextmenu", function (ev) {
                    renderer.handle_mouse(ev);
                })
                .on("keydown.dungeonContext", function (ev) {
                    if (ev.key === "ContextMenu" || (ev.shiftKey && ev.key === "F10")) {
                        ev.preventDefault(); ev.stopImmediatePropagation();
                        $(element).trigger($.Event("cell_contextmenu", { cell: renderer.view_center }));
                    }
                });

            cr.DungeonCellRenderer.prototype.init.call(this, element);
        },

        handle_mouse: function (ev)
        {
            if (ev.type === "mouseleave") presence.leave();
            if (!options.get("tile_web_mouse_control"))
                return;
            if (ev.type === "mouseleave")
            {
                if (this.tooltip_timeout)
                {
                    clearTimeout(this.tooltip_timeout);
                    this.tooltip_timeout = null;
                }

                view_data.remove_cursor(enums.CURSOR_MOUSE);
            }
            else
            {
                // Pointer coordinates are relative to the canvas, including
                // headers or other surrounding chrome and device pixel ratio.
                var bounds = this.element.getBoundingClientRect();
                let scaled = this.scaled_size(ev.clientX - bounds.left, ev.clientY - bounds.top);
                let cell_size = this.scaled_size();
                var loc = {
                    x: Math.floor(scaled.width / cell_size.width) + this.view.x,
                    y: Math.floor(scaled.height / cell_size.height) + this.view.y
                };

                view_data.place_cursor(enums.CURSOR_MOUSE, loc);
                presence.point(loc, ev);

                if (game.can_target() && ev.type !== "contextmenu" && !(ev.type === "mousedown" && (ev.which === 3 || ev.ctrlKey)))
                {
                    // XX refactor into mouse_control.js?
                    if (loc.x != this.last_sent_cursor.x
                        || loc.y != this.last_sent_cursor.y)
                    {
                        this.last_sent_cursor = {x: loc.x, y: loc.y};
                        comm.send_message("target_cursor",
                                                    this.last_sent_cursor);
                    }
                }

                if (ev.type === "mousemove")
                {

                    if (this.tooltip_timeout)
                        clearTimeout(this.tooltip_timeout);

                    var element = this.element;
                    this.tooltip_timeout = setTimeout(function () {
                        var new_ev = $.extend({}, ev, {
                            type: "cell_tooltip",
                            cell: loc
                        });
                        $(element).trigger(new_ev);
                    }, tip_policy.hover_ms);
                }
                else if (ev.type === "mousedown" || ev.type === "contextmenu")
                {
                    var new_ev = $.extend({}, ev, {
                        type: ev.type === "contextmenu" ? "cell_contextmenu" : "cell_click",
                        cell: loc
                    });
                    $(this.element).trigger(new_ev);
                }
            }
        },

        set_size: function (c, r)
        {
            var cell = this.scaled_size();
            var pixel_width = c * cell.width, pixel_height = r * cell.height;
            if ((this.cols == c) && (this.rows == r) &&
                (this.element.width == pixel_width) &&
                (this.element.height == pixel_height))
                return;

            this.cols = c;
            this.rows = r;
            this.view.x = this.view_center.x - Math.floor(c / 2);
            this.view.y = this.view_center.y - Math.floor(r / 2);
            // Match the integer device pixels used to paint each tile, even
            // when browser zoom produces a fractional device pixel ratio.
            util.init_canvas(this.element, pixel_width / window.devicePixelRatio,
                             pixel_height / window.devicePixelRatio);
            this.element.width = pixel_width;
            this.element.height = pixel_height;
            this.init(this.element);
            this.clear(); // clear the canvas and override default alpha fill
        },

        set_view_center: function(x, y)
        {
            this.view_center.x = x;
            this.view_center.y = y;
            this.view = {
                x: x - Math.floor(this.cols / 2),
                y: y - Math.floor(this.rows / 2)
            };
            $(document).trigger("game_camera_changed", [{ x: x, y: y }]);
        },

        // convert grid coordinates/dimensions to scaled canvas coordinates
        // by default, use map grid coordinates; set screen_grid to instead
        // use the visible grid (with 0,0 in the upper left of the screen)
        canvas_coords: function(cx, cy, cw, ch, screen_grid)
        {
            let scaled_cell = this.scaled_size();
            cw = cw || 1;
            ch = ch || 1;
            cx = cx || 0;
            cy = cy || 0;
            if (!screen_grid)
            {
                cx -= this.view.x;
                cy -= this.view.y;
            }
            return {
                x: cx * scaled_cell.width,
                y: cy * scaled_cell.height,
                width: cw * scaled_cell.width,
                height: ch * scaled_cell.height
            };
        },

        render_view: function(dirty)
        {
            // All terrain shaders in this paint share one phase at tile seams.
            this.frame_time = window.performance ? window.performance.now() : Date.now();
            var signature = [this.view.x, this.view.y, this.cols, this.rows,
                this.element.width, this.element.height, this.cell_width, this.cell_height].join(":");
            var full = !dirty || signature !== this.paint_signature;
            this.paint_signature = signature;
            this.sprite_reach = this.sprite_reach || 1;
            var cx, cy;
            for (cy = this.view.y; cy < this.view.y + this.rows; cy++)
                for (cx = this.view.x; cx < this.view.x + this.cols; cx++)
                    this.sprite_reach = Math.max(this.sprite_reach, spriteReach(map_knowledge.get(cx, cy).t));
            var damage = full ? null : chunks.plan({ x: this.view.x, y: this.view.y,
                cols: this.cols, rows: this.rows }, dirty, this.sprite_reach);
            if (damage && !damage.rectangles.length) {
                this.last_paint = { chunks: 0, cells: 0, full: false }; return;
            }
            this.ctx.save();
            try {
                if (damage) {
                    this.ctx.beginPath();
                    var renderer = this;
                    damage.rectangles.forEach(function (rect) {
                        var point = renderer.canvas_coords(rect.left, rect.top, rect.right - rect.left, rect.bottom - rect.top);
                        renderer.ctx.rect(point.x, point.y, point.width, point.height);
                    });
                    // A single union clip preserves exact-once translucent
                    // compositing at chunk seams and original depth ordering.
                    this.ctx.clip();
                }
                this.clear();
                var count = 0;
                for (cy = this.view.y; cy < this.view.y + this.rows; cy++)
                    for (cx = this.view.x; cx < this.view.x + this.cols; cx++)
                        if (!damage || damage.includes(cx, cy)) { this.render_grid_cell(cx, cy); count++; }
                this.last_paint = { chunks: damage ? damage.rectangles.length : null, cells: count, full: full };
            } finally { this.ctx.restore(); }
        },

        fit_to: function(width, height, min_diameter)
        {
            var scale;
            if (this.ui_state == enums.ui.VIEW_MAP)
                scale = options.get("tile_map_scale");
            else
                scale = options.get("tile_viewport_scale");
            var tile_size = Math.floor(options.get("tile_cell_pixels")
                                * scale / 100);
            var cell_size = {
                w: Math.floor(tile_size),
                h: Math.floor(tile_size)
            };

            if (options.get("tile_display_mode") == "glyphs")
            {
                // TODO: this should rescale to ensure los, similar to tiles
                this.glyph_mode_update_font_metrics();
                this.set_cell_size(this.glyph_mode_font_width,
                                    this.glyph_mode_line_height);
            }
            else if ((min_diameter * cell_size.w > width)
                || (min_diameter * cell_size.h > height))
            {
                // TODO: this produces bad results in hybrid mode, because the
                // font size isn't appropriately updated
                // scale down if necessary, so that los is in view
                var rescale = Math.min(width / (min_diameter * cell_size.w),
                                     height / (min_diameter * cell_size.h));
                this.set_cell_size(Math.floor(cell_size.w * rescale),
                                   Math.floor(cell_size.h * rescale));
            }
            else
                this.set_cell_size(cell_size.w, cell_size.h);

            // Explicit dungeon zoom may crop the visible region; canvas geometry
            // and hit testing use the same integer cell dimensions.
            if (this.ui_state === enums.ui.NORMAL && options.get("tile_display_mode") !== "glyphs") {
                var zoom = this.viewport_zoom || 1;
                this.set_cell_size(Math.max(1, Math.floor(this.cell_width * zoom)),
                                   Math.max(1, Math.floor(this.cell_height * zoom)));
            }

            var viewport = this.element.parentElement;
            var framed = viewport && viewport.id === "dungeon_viewport";
            var bleed = framed ? 12 : 0;
            var ratio = window.devicePixelRatio, unit = this.scaled_size();
            // Layout uses exact available pixels; render complete tiles beyond
            // every edge so zoom cannot leave gaps or move neighboring panels.
            // Odd counts keep the followed tile centered at every zoom level.
            var view_width = Math.max(1, 2 * Math.ceil(((width + bleed * 2) * ratio / unit.width - 1) / 2) + 1);
            var view_height = Math.max(1, 2 * Math.ceil(((height + bleed * 2) * ratio / unit.height - 1) / 2) + 1);
            this.set_size(view_width, view_height);
            if (framed) {
                viewport.style.width = width + "px";
                viewport.style.height = height + "px";
                this.element.style.left = Math.floor((width * ratio - this.element.width) / 2) / ratio + "px";
                this.element.style.top = Math.floor((height * ratio - this.element.height) / 2) / ratio + "px";
            }
        },

        in_view: function(cx, cy)
        {
            return (cx >= this.view.x) && (this.view.x + this.cols > cx) &&
                (cy >= this.view.y) && (this.view.y + this.rows > cy);
        },

        // render a single cell on the map grid
        render_grid_cell: function(cx, cy, map_cell, cell)
        {
            if (!this.in_view(cx, cy))
                return;
            map_cell = map_cell || map_knowledge.get(cx, cy);
            cell = cell || map_cell.t;
            let scaled = this.canvas_coords(cx, cy);
            this.render_cell(cx, cy, scaled.x, scaled.y, map_cell, cell);
            presence.draw(this, cx, cy, scaled.x, scaled.y);
        },

        // Cursor and peer-hover changes use the same frame as native updates.
        render_loc: function(cx, cy)
        {
            map_knowledge.touch(cx, cy);
            $(document).trigger("dungeon_tiles_changed", [[{ x: cx, y: cy }]]);
        },

        animate: function ()
        {
            var tick = Math.floor(window.performance.now() / 250);
            var background = !options.get("tile_realtime_anim") || tick !== last_background_tick;
            if (background) {
                last_background_tick = tick; global_anim_counter++;
                if (global_anim_counter >= 65536) global_anim_counter = 0;
            }
            var changed = [];

            for (var cy = this.view.y; cy < this.view.y + this.rows; ++cy)
                for (var cx = this.view.x; cx < this.view.x + this.cols; ++cx)
            {
                var map_cell = map_knowledge.get(cx, cy);
                var cell = map_cell.t;
                if (map_knowledge.visible(map_cell) && (background && background_is_animated(cell)
                    || effects.animated(cell) || regions.animated(cell, cx, cy, this)))
                {
                    if (background) animate_cell(cell);
                    map_knowledge.touch(cx, cy);
                    changed.push({ x: cx, y: cy });
                }
            }
            if (changed.length)
                $(document).trigger("dungeon_tiles_changed", [changed]);
        },

        // This is mostly here so that it can inherit cell size
        new_renderer: function(tiles)
        {
            tiles = tiles || [];
            var renderer = new cr.DungeonCellRenderer();
            var canvas = $("<canvas>");
            renderer.set_cell_size(this.cell_width,
                                   this.cell_height);
            util.init_canvas(canvas[0], this.cell_width, this.cell_height);
            renderer.init(canvas[0]);
            renderer.draw_tiles(tiles);

            return renderer;
        },

        set_ui_state: function(s)
        {
            this.ui_state = s;
        },

        update_mouse_mode: function (m)
        {
            if (!game.can_target())
                this.last_sent_cursor = { x: 0, y: 0 };
        },
    });

    var renderer = new DungeonViewRenderer();
    presence.attach(renderer);
    traversal.attach(renderer);
    chains.attach(renderer);
    shells.attach(renderer);
    movement.attach(renderer);
    plannedRoute.attach(renderer);
    var anim_interval = null, animation_running = false;

    function update_animation_interval()
    {
        if (anim_interval)
        {
            clearTimeout(anim_interval);
            anim_interval = null;
        }
        if (animation_running && options.get("tile_realtime_anim"))
        {
            anim_interval = setInterval(function () {
                renderer.animate();
            }, effects.fast && effects.fast() ? 100 : 250);
        }
    }

    options.add_listener(update_animation_interval);
    $(document).on("visual_presentation_changed.dungeon_renderer premium_animation_cadence_changed.dungeon_renderer visibilitychange.dungeon_renderer game_ui_changed.dungeon_renderer", update_animation_interval);

    $(document).off("game_init.dungeon_renderer");
    $(document).on("game_init.dungeon_renderer", function () {
        animation_running = true; last_background_tick = -1;
        renderer.cols = 0;
        renderer.rows = 0;
        renderer.view = { x: 0, y: 0 };
        renderer.view_center = { x: 0, y: 0 };
        renderer.paint_signature = null;
        renderer.sprite_reach = 1;

        renderer.init($("#dungeon")[0]);
        update_animation_interval();
    });

    $(document).off("game_cleanup.dungeon_renderer")
        .on("game_cleanup.dungeon_renderer game_connection_lost.dungeon_renderer game_preinit.dungeon_renderer", function () {
            animation_running = false;
            if (anim_interval)
            {
                clearTimeout(anim_interval);
                anim_interval = null;
            }
        });

    /* Hack to show animations (if real-time ones are not enabled)
       even in turns where nothing else happens */
    $(document).off("text_update.dungeon_renderer")
        .on("text_update.dungeon_renderer", function () {
            renderer.animate();
        });

    return renderer;
});

webserver/game_data/static/cell_renderer.text:
define(["jquery", "./view_data", "./tileinfo-main", "./tileinfo-player",
        "./tileinfo-icons", "./tileinfo-dngn", "./enums", "./map_knowledge",
        "./player", "./options", "./cell-renderer-glyphs", "./cell-renderer-overlays",
        "./cell-renderer-layers", "./cell-renderer-textures", "./shell-animation", "contrib/jquery.json"],
function ($, view_data, main, tileinfo_player, icons, dngn, enums, map_knowledge,
          player, options, glyphs, overlays, layers, textures, shells) {
    "use strict";

    function DungeonCellRenderer()
    {
        this.set_cell_size(32, 32);
    }

    var in_water = layers.in_water;

    function obj_to_str(o)
    {
        return $.toJSON(o);
    }

    $.extend(DungeonCellRenderer.prototype, glyphs.methods, overlays,
        layers.methods, textures, {
        init: function(element)
        {
            this.element = element;
            this.ctx = this.element.getContext("2d");
        },

        set_cell_size: function(w, h)
        {
            this.cell_width = Math.floor(w);
            this.cell_height = Math.floor(h);
            this.x_scale = this.cell_width / 32;
            this.y_scale = this.cell_height / 32;
        },

        render_cursors: function(cx, cy, x, y)
        {
            var renderer = this;
            $.each(view_data.cursor_locs, function (type, loc) {
                if (loc && (loc.x == cx) && (loc.y == cy))
                {
                    var idx;

                    switch (type)
                    {
                    case enums.CURSOR_TUTORIAL:
                        idx = icons.TUTORIAL_CURSOR;
                        break;
                    case enums.CURSOR_MOUSE:
                        idx = icons.CURSOR;
                        // TODO: tilei.CURSOR2 if not visible
                        break;
                    case enums.CURSOR_MAP:
                        idx = icons.CURSOR;
                        break;
                    }

                    renderer.draw_icon(idx, x, y);
                }
            });
        },

        scaled_size: function(w, h)
        {
            w = w === undefined ? this.cell_width : w;
            h = h === undefined ? this.cell_height : h;
            const ratio = window.devicePixelRatio;
            const width = Math.floor(w * ratio);
            const height = Math.floor(h * ratio);
            return {width: width, height: height};
        },

        clear: function()
        {
            this.ctx.fillStyle = "black";
            // element dimensions are already scaled
            this.ctx.fillRect(0, 0, this.element.width, this.element.height);
        },

        do_render_cell: function(cx, cy, x, y, map_cell, cell)
        {
            let scaled = this.scaled_size();

            this.ctx.fillStyle = "black";
            this.ctx.fillRect(x, y, scaled.width, scaled.height);

            map_cell = map_cell || map_knowledge.get(cx, cy);
            cell = cell || map_cell.t;

            if (!cell)
            {
                this.render_cursors(cx, cy, x, y);
                this.render_party_overlays(cx, cy, x, y);
                return;
            }

            // track whether this cell overlaps to the top or left
            this.current_sy = 0;
            this.current_left_overlap = 0;

            cell.fg = enums.prepare_fg_flags(cell.fg || 0);
            cell.bg = enums.prepare_bg_flags(cell.bg || 0);
            cell.cloud = enums.prepare_fg_flags(cell.cloud || 0);
            cell.icons = cell.icons || [];
            cell.flv = cell.flv || {};
            cell.flv.f = cell.flv.f || 0;
            cell.flv.s = cell.flv.s || 0;
            map_cell.g = map_cell.g || ' ';
            if (map_cell.col == undefined) map_cell.col = 7;

            if (options.get("tile_display_mode") == "glyphs")
            {
                this.render_glyph(x, y, map_cell, false);

                this.render_cursors(cx, cy, x, y);
                this.render_party_overlays(cx, cy, x, y);
                return;
            }

            // cell is basically a packed_cell + doll + mcache entries
            if (options.get("tile_display_mode") == "tiles")
                this.draw_background(x, y, cell, cx, cy);

            if (cell.ritual_blood)
            {
                // Floor resource markers stay under actors and targeting UI.
                var units = cell.ritual_blood & 3;
                var fading = Boolean(cell.ritual_blood & 4);
                var sx = scaled.width / 32, sy = scaled.height / 32;
                this.ctx.save();
                this.ctx.fillStyle = fading ? "#8d4b56" : "#ef9e9d";
                for (var drop = 0; drop < units; drop++)
                    this.ctx.fillRect(x + (5 + drop * 4) * sx, y + 27 * sy, sx, (fading ? 1 : 2) * sy);
                if (!fading)
                    this.ctx.fillRect(x + 4 * sx, y + 25 * sy, 2 * sx, sy);
                this.ctx.restore();
            }

            var fg_idx = cell.fg.value;
            var is_in_water = in_water(cell);

            // draw clouds
            if (cell.cloud.value)
            {
                this.ctx.save();
                // If there will be a front/back cloud pair, draw
                // the underlying one with correct alpha
                if (fg_idx)
                {
                    try
                    {
                        this.ctx.globalAlpha = 0.6;
                        this.set_nonsubmerged_clip(x, y, 20);
                        layers.paintEffect(this, cell.cloud.value, "cloud", cx, cy, x, y);
                    }
                    finally
                    {
                        this.ctx.restore();
                    }

                    this.ctx.save();
                    try
                    {
                        this.ctx.globalAlpha = 0.2;
                        this.set_submerged_clip(x, y, 20);
                        layers.paintEffect(this, cell.cloud.value, "cloud", cx, cy, x, y);
                    }
                    finally
                    {
                        this.ctx.restore();
                    }
                }
                else
                {
                    try
                    {
                        this.ctx.globalAlpha = 1.0;
                        layers.paintEffect(this, cell.cloud.value, "cloud", cx, cy, x, y);
                    }
                    finally
                    {
                        this.ctx.restore();
                    }
                }
            }

            // Canvas doesn't support applying an alpha gradient
            // to an image while drawing; so to achieve the same
            // effect as in local tiles, it would probably be best
            // to pregenerate water tiles with the (inverse) alpha
            // gradient built in. This simply draws the lower
            // half with increased transparency; for now, it looks
            // good enough.

            var renderer = this;
            function draw_dolls()
            {
                if (!shells.draw(renderer, cx, cy, x, y, draw_default_dolls,
                    fg_idx >= main.MAIN_MAX && Boolean(cell.doll || cell.mcache)))
                    draw_default_dolls();
            }
            function draw_default_dolls()
            {
                if ((fg_idx >= main.MAIN_MAX) && cell.doll)
                {
                    var mcache_map = {};
                    if (cell.mcache)
                    {
                        for (var i = 0; i < cell.mcache.length; ++i)
                            mcache_map[cell.mcache[i][0]] = i;
                    }
                    $.each(cell.doll, function (i, doll_part) {
                        var xofs = 0;
                        var yofs = 0;
                        if (mcache_map[doll_part[0]] !== undefined)
                        {
                            var mind = mcache_map[doll_part[0]];
                            xofs = cell.mcache[mind][1];
                            yofs = cell.mcache[mind][2];
                        }
                        renderer.draw_player(doll_part[0],
                                             x, y, xofs, yofs, doll_part[1]);
                    });
                }

                if ((fg_idx >= tileinfo_player.MCACHE_START) && cell.mcache)
                {
                    $.each(cell.mcache, function (i, mcache_part) {
                        if (mcache_part) {
                            renderer.draw_player(mcache_part[0],
                                                 x, y, mcache_part[1], mcache_part[2]);
                        }
                    });
                }
            }

            layers.paintActor(this, cx, cy, x, y, map_cell, function () {
            if (is_in_water && options.get("tile_display_mode") == "tiles")
            {
                this.ctx.save();
                try
                {
                    this.ctx.globalAlpha = cell.trans ? 0.5 : 1.0;

                    this.set_nonsubmerged_clip(x, y, 20);

                    draw_dolls();
                }
                finally
                {
                    this.ctx.restore();
                }

                this.ctx.save();
                try
                {
                    this.ctx.globalAlpha = cell.trans ? 0.1 : 0.3;
                    this.set_submerged_clip(x, y, 20);

                    draw_dolls();
                }
                finally
                {
                    this.ctx.restore();
                }
            }
            else if (options.get("tile_display_mode") == "tiles")
            {
                this.ctx.save();
                try
                {
                    this.ctx.globalAlpha = cell.trans ? 0.55 : 1.0;

                    draw_dolls();
                }
                finally
                {
                    this.ctx.restore();
                }
            }

            }.bind(this));
            this.draw_foreground(x, y, map_cell);

            // draw clouds over stuff
            if (fg_idx && cell.cloud.value)
            {
                this.ctx.save();
                try
                {
                    this.ctx.globalAlpha = 0.4;
                    this.set_nonsubmerged_clip(x, y, 20);
                    layers.paintEffect(this, cell.cloud.value, "cloud", cx, cy, x, y);
                }
                finally
                {
                    this.ctx.restore();
                }

                this.ctx.save();
                try
                {
                    this.ctx.globalAlpha = 0.8;
                    this.set_submerged_clip(x, y, 20);
                    layers.paintEffect(this, cell.cloud.value, "cloud", cx, cy, x, y);
                }
                finally
                {
                    this.ctx.restore();
                }
            }

            // Draw main-tile overlays (i.e. zaps), on top of clouds.
            if (cell.ov)
            {
                $.each(cell.ov, function (i, overlay)
                        {
                            if (dngn.FEAT_MAX <= overlay && overlay < main.MAIN_MAX)
                            {
                                layers.paintEffect(renderer, overlay, "overlay", cx, cy, x, y);
                            }
                        });
            }

            this.render_flash(x, y, map_cell);

            this.render_cursors(cx, cy, x, y);

            if (cx == player.pos.x && cy == player.pos.y
                && map_knowledge.player_on_level())
            {
                this.draw_minibars(x, y);
            }

            this.render_party_overlays(cx, cy, x, y);

            // Debug helper
            if (cell.mark)
            {
                this.ctx.fillStyle = "red";
                this.ctx.font = "12px monospace";
                this.ctx.textAlign = "center";
                this.ctx.textBaseline = "middle";
                let scaled = this.scaled_size();
                this.ctx.fillText(cell.mark,
                                  x + 0.5 * scaled.width,
                                  y + 0.5 * scaled.height);
            }

            cell.sy = this.current_sy;
            cell.left_overlap = this.current_left_overlap;
        },

        render_cell: function()
        {
            if (window.debug_mode)
                this.do_render_cell.apply(this, arguments);
            else
            {
                try
                {
                    this.do_render_cell.apply(this, arguments);
                }
                catch (err)
                {
                    var cx = arguments[0];
                    var cy = arguments[1];
                    var cell = arguments[5];
                    console.error("Error while drawing cell " + obj_to_str(cell)
                                  + " at " + cx + "/" + cy + ": " + err);
                }
            }
        },

        render_flash: function(x, y, map_cell)
        {
            if (map_cell.flc)
            {
                var col = view_data.get_flash_colour(map_cell.flc, map_cell.fla);
                this.ctx.save();
                try
                {
                    this.ctx.fillStyle = "rgb(" + col.r + "," +
                        col.g + "," + col.b + ")";
                    this.ctx.globalAlpha = col.a / 255;
                    const cell = this.scaled_size();
                    this.ctx.fillRect(x, y, cell.width, cell.height);
                }
                finally
                {
                    this.ctx.restore();
                }
            }
        },

    });

    $(document).off("game_init.cell_renderer")
        .on("game_init.cell_renderer", function () {
            glyphs.determine_colours();
        });

    return {
        DungeonCellRenderer: DungeonCellRenderer,
    };
});

