                        .attr("data-tip-body", weap_str + " | Move: " + (mv_aut / 10).toFixed(1) + "t (" + mv_aut + " aut) | Atk: " + (ak_aut / 10).toFixed(1) + "t (" + ak_aut + " aut)")
                );

